negativeExample:
package test;

// Mock classes for compilation
interface IInformationControl { }
interface IInformationControlCreator { IInformationControl createInformationControl(Shell parent); }
class DefaultInformationControl implements IInformationControl {
    public DefaultInformationControl(Shell parent) {}
    public DefaultInformationControl() {}
}
class Shell { public Shell() {} }

public class Example {
    public IInformationControlCreator getCreatorWithExtraLogic() {
        return new IInformationControlCreator() {
            @Override
            public IInformationControl createInformationControl(Shell parent) {
                System.out.println("Creating control"); // extra logic
                return new DefaultInformationControl(parent);
            }
        };
    }

    public IInformationControlCreator getCreatorWithNoArgsConstructor() {
        return new IInformationControlCreator() {
            @Override
            public IInformationControl createInformationControl(Shell parent) {
                return new DefaultInformationControl(); // different constructor
            }
        };
    }

    public IInformationControlCreator getCreatorWithDifferentParamName() {
        return new IInformationControlCreator() {
            @Override
            public IInformationControl createInformationControl(Shell someOtherParent) { // different parameter name
                return new DefaultInformationControl(someOtherParent);
            }
        };
    }

    public IInformationControlCreator getCreatorWithDifferentCtorParam() {
        return new IInformationControlCreator() {
            @Override
            public IInformationControl createInformationControl(Shell parent) {
                return new DefaultInformationControl(new Shell()); // new instance as ctor param
            }
        };
    }
}
